package com.tcgexporter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TcgExporterPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TcgExporterPlugin.class);
		RuneLite.main(args);
	}
}

package com.tcgexporter;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;

/**
 * Regression test for a fresh, independent re-implementation of osrs-tcg's RLTCG_v2 decode.
 * The fixture below is real output of the actual encode algorithm (gzip -> XOR with osrs-tcg's
 * published salt -> base64), generated once via a small Python script mirroring
 * TcgStateStorageEncoding.encode() exactly -- not hand-written -- encoding:
 *   cardEntries: [
 *     {cardName: "Abyssal whip", variants: [{foil: true, pulledBy: "Zezima", pulledAt: 1712345678901}]},
 *     {cardName: "'24-carat' sword", variants: [{pulledAt: 1700000000000}]}
 *   ]
 */
public class TcgCollectionDecoderTest
{
	private static final String FIXTURE = "RLTCG_v2:TcdcQ5MrBxlwjEj5UmijYlzRvA2v6nZh+Q2+5e6K8c/SouMbByF4GqZwapj8gVRZsuEHsM4JHM/aydagQRbzGYQP+fX+"
		+ "JE2Roh+Kgl3tDygM63U7gs9OWWC7X/m+e96TD2ZqjFyqOcJIofoT+TLBuVuFkMab72j0UrOGgVRp9vulOpe91dxpnqlI8SIlf1RZoc13heH3mLOWBh+IdHlZlAp6"
		+ "jrWyjUxUQw==";

	private final Gson gson = new Gson();

	@Test
	public void decodesRealFixtureCorrectly()
	{
		List<OwnedInstance> instances = TcgCollectionDecoder.decode(gson, FIXTURE);
		assertEquals(2, instances.size());

		Map<String, OwnedInstance> byName = new java.util.HashMap<>();
		for (OwnedInstance inst : instances)
		{
			byName.put(inst.cardName, inst);
		}

		OwnedInstance whip = byName.get("Abyssal whip");
		assertTrue("Abyssal whip should be present", whip != null);
		assertTrue("Abyssal whip should be foil", whip.foil);
		assertEquals(1712345678901L, whip.pulledAtEpochMs);

		OwnedInstance sword = byName.get("'24-carat' sword");
		assertTrue("sword should be present", sword != null);
		assertFalse("sword should not be foil", sword.foil);
		assertEquals(1700000000000L, sword.pulledAtEpochMs);
	}

	@Test
	public void emptyOrMissingPrefixReturnsEmptyList()
	{
		assertTrue(TcgCollectionDecoder.decode(gson, "").isEmpty());
		assertTrue(TcgCollectionDecoder.decode(gson, null).isEmpty());
		assertTrue(TcgCollectionDecoder.decode(gson, "not-the-right-format").isEmpty());
	}
}

package com.tcgexporter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("tcgexporter")
public interface TcgExporterConfig extends Config
{
	@ConfigItem(
		keyName = "webhook",
		name = "Webhook URL",
		description = "Full URL to POST your osrs-tcg collection to. Empty (the default) means "
			+ "the plugin does nothing -- this is opt-in. Ask whoever runs your group's server for "
			+ "this URL.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 0
	)
	default String webhook()
	{
		return "";
	}

	@ConfigItem(
		keyName = "apiKey",
		name = "API key",
		description = "Your personal API key for the webhook, issued by whoever runs the server. "
			+ "Sent as the X-Api-Key header on every export.",
		secret = true,
		position = 1
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "periodSeconds",
		name = "Checkpoint period (seconds)",
		description = "New/sold cards are also exported immediately via osrs-tcg's live update API when "
			+ "available (foil status and pull time not yet known at that point). This setting controls "
			+ "how often, separately, to re-check osrs-tcg's actual saved checkpoint for the real foil/"
			+ "timestamp data, in seconds. Nothing is sent if nothing changed since the last export. Run "
			+ "::tcg-save in chat, or log out, to force that checkpoint sooner instead of waiting.",
		position = 2
	)
	default int periodSeconds()
	{
		return 30;
	}
}

package com.tcgexporter;

import com.google.gson.Gson;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Objects;
import java.util.zip.GZIPInputStream;
import lombok.extern.slf4j.Slf4j;

/**
 * Reads osrs-tcg's own collection out of {@code ConfigManager.getRSProfileConfiguration("osrstcg", "state")}.
 * <p>
 * Reimplemented here rather than imported: this plugin has no compile-time dependency on osrs-tcg (a separate
 * Hub artifact with its own classloader), and the on-disk format is osrs-tcg's own publicly-documented encoding
 * (gzip -> XOR with a fixed salt -> base64, see its {@code TcgStateStorageEncoding}/{@code TcgStateCodec}) --
 * there is nothing secret being reversed here, just a transform this plugin needs to mirror. Deliberately kept
 * independent from any other project's copy of this same logic (e.g. a private companion tool) -- this plugin
 * is meant to stand alone and be Hub-reviewable on its own.
 */
@Slf4j
final class TcgCollectionDecoder
{
	private static final String STORAGE_PREFIX = "RLTCG_v2:";

	// Must match osrs-tcg's TcgStateStorageEncoding.XOR_SALT exactly.
	private static final byte[] XOR_SALT = {
		(byte) 0x52, (byte) 0x4c, (byte) 0x54, (byte) 0x43, (byte) 0x47,
		(byte) 0x7c, (byte) 0x6f, (byte) 0x73, (byte) 0x72, (byte) 0x73,
		(byte) 0x2d, (byte) 0x74, (byte) 0x63, (byte) 0x67, (byte) 0x21,
	};

	private TcgCollectionDecoder()
	{
	}

	/**
	 * @param rawState the raw string from {@code ConfigManager.getRSProfileConfiguration("osrstcg", "state")}
	 * @return owned instances, or an empty list if osrs-tcg isn't installed / has no state / the format changed
	 */
	static List<OwnedInstance> decode(Gson gson, String rawState)
	{
		String plainJson = decodeToJson(rawState);
		if (plainJson.isEmpty())
		{
			return List.of();
		}

		SerializedState state;
		try
		{
			state = gson.fromJson(plainJson, SerializedState.class);
		}
		catch (Exception ex)
		{
			log.debug("Failed to parse osrs-tcg state JSON (format may have changed upstream)", ex);
			return List.of();
		}
		if (state == null)
		{
			return List.of();
		}

		if (state.cardEntries != null && !state.cardEntries.isEmpty())
		{
			return fromCardEntries(state.cardEntries);
		}
		return fromLegacyInstances(state.cardInstances);
	}

	private static String decodeToJson(String stored)
	{
		String s = Objects.requireNonNullElse(stored, "");
		if (s.isEmpty() || !s.startsWith(STORAGE_PREFIX))
		{
			return "";
		}
		try
		{
			byte[] compressed = Base64.getDecoder().decode(s.substring(STORAGE_PREFIX.length()));
			xorWithSalt(compressed);
			try (GZIPInputStream gzis = new GZIPInputStream(new ByteArrayInputStream(compressed)))
			{
				return new String(gzis.readAllBytes(), StandardCharsets.UTF_8);
			}
		}
		catch (IllegalArgumentException | IOException ex)
		{
			log.debug("Failed to decode osrs-tcg state (format may have changed upstream)", ex);
			return "";
		}
	}

	private static void xorWithSalt(byte[] data)
	{
		for (int i = 0; i < data.length; i++)
		{
			data[i] ^= XOR_SALT[i % XOR_SALT.length];
		}
	}

	private static List<OwnedInstance> fromCardEntries(List<CardEntryDto> entries)
	{
		List<OwnedInstance> out = new ArrayList<>();
		for (CardEntryDto entry : entries)
		{
			if (entry == null || entry.cardName == null || entry.cardName.trim().isEmpty() || entry.variants == null)
			{
				continue;
			}
			String cardName = entry.cardName.trim();
			for (CardVariantDto variant : entry.variants)
			{
				if (variant == null)
				{
					continue;
				}
				// Fresh (schemaVersion 5) saves write exactly one variant per physical copy, so quantity is
				// normally absent. We don't expand a batched legacy quantity into N duplicate rows -- a
				// webhook consumer only needs to know a (card, foil) pair exists, not how many copies.
				int quantity = variant.quantity == null ? 1 : variant.quantity;
				if (quantity <= 0)
				{
					continue;
				}
				boolean foil = Boolean.TRUE.equals(variant.foil);
				long pulledAt = variant.pulledAt == null ? 0L : Math.max(0L, variant.pulledAt);
				out.add(new OwnedInstance(cardName, foil, pulledAt));
			}
		}
		return out;
	}

	private static List<OwnedInstance> fromLegacyInstances(List<LegacyInstanceDto> instances)
	{
		List<OwnedInstance> out = new ArrayList<>();
		if (instances == null)
		{
			return out;
		}
		for (LegacyInstanceDto row : instances)
		{
			if (row == null || row.cardName == null || row.cardName.trim().isEmpty())
			{
				continue;
			}
			long pulledAt = Math.max(0L, row.pulledAt);
			out.add(new OwnedInstance(row.cardName.trim(), row.foil, pulledAt));
		}
		return out;
	}

	private static final class SerializedState
	{
		List<CardEntryDto> cardEntries;
		List<LegacyInstanceDto> cardInstances;
	}

	private static final class CardEntryDto
	{
		String cardName;
		List<CardVariantDto> variants;
	}

	private static final class CardVariantDto
	{
		Boolean foil;
		Long pulledAt;
		Integer quantity;
		String pulledBy; // unused: this plugin exports per-account collections, not in-game pull attribution
	}

	private static final class LegacyInstanceDto
	{
		String cardName;
		boolean foil;
		long pulledAt;
	}
}

package com.tcgexporter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.io.IOException;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Reads your locally-pulled osrs-tcg card collection (name, foil, when you pulled it) and POSTs it to a
 * webhook URL you configure. Read-only towards osrs-tcg -- see {@link TcgCollectionDecoder} -- and does
 * nothing at all until both a webhook URL and API key are configured (opt-in by default).
 * <p>
 * Two complementary export paths feed the same webhook:
 * <ul>
 *     <li><b>Live path</b>: osrs-tcg's own {@code PluginMessage} API pushes the full set of owned card
 *     <i>names</i> the instant your collection changes (in-memory, no save/checkpoint involved) -- but
 *     that API folds away foil status and pull timestamps. New names are exported immediately with
 *     placeholder values ({@code foil=false}, {@code acquiredAtEpochMs=now}).</li>
 *     <li><b>Checkpoint path</b>: periodically decodes osrs-tcg's actual saved state via
 *     {@code ConfigManager}, which alone has the real foil/timestamp data, but is only updated on
 *     osrs-tcg's own save triggers (logout, shutdown, {@code ::tcg-save}, etc).</li>
 * </ul>
 * Whichever ran most recently wins for a given card, so a placeholder from the live path is
 * automatically corrected the next time the checkpoint path runs and finds the same card with accurate
 * data. A backend that treats each sync as that player's complete current collection (diffing and
 * replacing, not appending) self-heals this with no special-casing needed.
 * <p>
 * The export payload's shape is this plugin's own choice, not anything osrs-tcg defines: a JSON body
 * {@code {"instances":[{"cardName","foil","acquiredAtEpochMs"}, ...]}}, with the configured API key sent as
 * the {@code X-Api-Key} header. Point the webhook at whatever server you like that's willing to accept that.
 */
@Slf4j
@PluginDescriptor(
	name = "TCG Exporter",
	description = "Periodically exports your osrs-tcg card collection to a webhook you configure",
	tags = {"tcg", "cards", "collection", "export", "webhook"}
)
public class TcgExporterPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	// osrs-tcg's PluginMessage API (its OwnedCardNamesApiService). We post a query; it replies with
	// "owned-names" and pushes "owned-names-changed" after every collection change. String constants
	// are copied, not imported -- Hub plugins can't see each other's classes.
	private static final String TCG_API_NAMESPACE = "osrstcg";
	private static final String TCG_API_QUERY = "query-owned-names";
	private static final String TCG_API_REPLY = "owned-names";
	private static final String TCG_API_CHANGED = "owned-names-changed";
	private static final String TCG_API_NAMES_KEY = "ownedNames";

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private EventBus eventBus;

	@Inject
	private TcgExporterConfig config;

	// All touched from more than one thread (the @Schedule thread, the thread that dispatches
	// PluginMessage -- likely the client thread -- and OkHttp's callback thread), so every mutable
	// field here is either volatile or replaced wholesale with a fresh immutable snapshot.
	private volatile String lastSeenRawState;
	private volatile long lastFullCheckAttemptAtMs;
	private volatile String lastExportedSignature = "";
	private volatile Map<String, List<OwnedInstance>> lastKnownByName = Collections.emptyMap();
	// Null until the live API has answered at least once.
	private volatile Set<String> lastLiveNames;

	@Provides
	TcgExporterConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TcgExporterConfig.class);
	}

	@Override
	protected void startUp()
	{
		lastSeenRawState = null;
		lastFullCheckAttemptAtMs = 0L;
		lastExportedSignature = "";
		lastKnownByName = Collections.emptyMap();
		lastLiveNames = null;
	}

	@Override
	protected void shutDown()
	{
		lastSeenRawState = null;
		lastExportedSignature = "";
		lastKnownByName = Collections.emptyMap();
		lastLiveNames = null;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// A different account's collection is about to load -- forget everything about the old one
		// so its cards can never leak into the new profile's export, then re-baseline.
		lastLiveNames = null;
		lastKnownByName = Collections.emptyMap();
		lastExportedSignature = "";
		lastSeenRawState = null;
		queryLiveApi();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event)
	{
		if (!TCG_API_NAMESPACE.equals(event.getNamespace())
			|| (!TCG_API_REPLY.equals(event.getName()) && !TCG_API_CHANGED.equals(event.getName())))
		{
			return;
		}

		Map<String, Object> data = event.getData();
		Object namesObj = data == null ? null : data.get(TCG_API_NAMES_KEY);
		if (!(namesObj instanceof List))
		{
			return;
		}

		Set<String> names = new LinkedHashSet<>();
		for (Object n : (List<?>) namesObj)
		{
			if (n instanceof String)
			{
				String trimmed = ((String) n).trim();
				if (!trimmed.isEmpty())
				{
					names.add(trimmed);
				}
			}
		}
		lastLiveNames = names;

		String webhook = config.webhook().trim();
		String apiKey = config.apiKey().trim();
		if (webhook.isEmpty() || apiKey.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		maybeExport(webhook, apiKey, mergeLiveNames(names));
	}

	@Schedule(period = 5, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void tick()
	{
		if (lastLiveNames == null)
		{
			// Cheap retry until osrs-tcg answers -- harmless no-op if it isn't installed at all.
			queryLiveApi();
		}

		String webhook = config.webhook().trim();
		String apiKey = config.apiKey().trim();
		if (webhook.isEmpty() || apiKey.isEmpty())
		{
			// Opt-in: this plugin does nothing until both are configured.
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int periodSeconds = Math.max(5, config.periodSeconds());
		long now = System.currentTimeMillis();
		if (now - lastFullCheckAttemptAtMs < periodSeconds * 1000L)
		{
			return;
		}
		lastFullCheckAttemptAtMs = now;

		String rawState = configManager.getRSProfileConfiguration("osrstcg", "state");
		if (rawState == null || rawState.isEmpty())
		{
			// osrs-tcg isn't installed, or hasn't saved a checkpoint yet.
			return;
		}
		if (rawState.equals(lastSeenRawState))
		{
			return;
		}
		lastSeenRawState = rawState;

		List<OwnedInstance> instances = TcgCollectionDecoder.decode(gson, rawState);
		// Accurate foil/timestamp data for the live path to merge with, whether or not this
		// particular checkpoint ends up being exported below.
		lastKnownByName = groupByName(instances);

		maybeExport(webhook, apiKey, instances);
	}

	private void queryLiveApi()
	{
		eventBus.post(new PluginMessage(TCG_API_NAMESPACE, TCG_API_QUERY));
	}

	/**
	 * Fills in the current best-known detail for a live name-only snapshot: known cards keep their
	 * real foil/timestamp from the last checkpoint decode, brand new names get a placeholder that a
	 * later checkpoint will correct. A name absent from {@code names} is simply not included --
	 * sold/traded-away cards drop out of the next export this way.
	 */
	private List<OwnedInstance> mergeLiveNames(Set<String> names)
	{
		Map<String, List<OwnedInstance>> known = lastKnownByName;
		List<OwnedInstance> merged = new ArrayList<>(names.size());
		long now = System.currentTimeMillis();
		for (String name : names)
		{
			List<OwnedInstance> variants = known.get(name);
			if (variants != null && !variants.isEmpty())
			{
				merged.addAll(variants);
			}
			else
			{
				merged.add(new OwnedInstance(name, false, now));
			}
		}
		return merged;
	}

	private static Map<String, List<OwnedInstance>> groupByName(List<OwnedInstance> instances)
	{
		Map<String, List<OwnedInstance>> byName = new HashMap<>();
		for (OwnedInstance inst : instances)
		{
			byName.computeIfAbsent(inst.cardName, k -> new ArrayList<>()).add(inst);
		}
		return byName;
	}

	private static String signatureOf(List<OwnedInstance> instances)
	{
		List<String> parts = new ArrayList<>(instances.size());
		for (OwnedInstance inst : instances)
		{
			parts.add(inst.cardName + "�" + inst.foil + "�" + inst.pulledAtEpochMs);
		}
		Collections.sort(parts);
		return String.join("\n", parts);
	}

	private void maybeExport(String webhook, String apiKey, List<OwnedInstance> instances)
	{
		if (instances.isEmpty())
		{
			return;
		}
		String signature = signatureOf(instances);
		if (signature.equals(lastExportedSignature))
		{
			return;
		}
		export(webhook, apiKey, instances, signature);
	}

	private void export(String webhook, String apiKey, List<OwnedInstance> instances, String signatureAtExportTime)
	{
		HttpUrl url = HttpUrl.parse(webhook);
		if (url == null)
		{
			log.debug("Webhook URL is not valid, skipping export: {}", webhook);
			return;
		}

		JsonArray array = new JsonArray();
		for (OwnedInstance inst : instances)
		{
			JsonObject obj = new JsonObject();
			obj.addProperty("cardName", inst.cardName);
			obj.addProperty("foil", inst.foil);
			obj.addProperty("acquiredAtEpochMs", inst.pulledAtEpochMs);
			array.add(obj);
		}
		JsonObject body = new JsonObject();
		body.add("instances", array);

		Request request = new Request.Builder()
			.url(url)
			.header("X-Api-Key", apiKey)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Export failed, will retry next change", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (response.isSuccessful())
				{
					lastExportedSignature = signatureAtExportTime;
				}
				else
				{
					log.debug("Webhook rejected export: HTTP {}", response.code());
				}
				response.close();
			}
		});
	}
}

package com.tcgexporter;

/** One owned copy of a card, as read from osrs-tcg's local collection. */
final class OwnedInstance
{
	final String cardName;
	final boolean foil;
	final long pulledAtEpochMs;

	OwnedInstance(String cardName, boolean foil, long pulledAtEpochMs)
	{
		this.cardName = cardName;
		this.foil = foil;
		this.pulledAtEpochMs = pulledAtEpochMs;
	}
}
